# Driver for gen_band_lean_v2.py (executed inside it, after the v1 definitions): one Lean module per subtree under the
# root's cut walls, and the final module BandCoverN with bc_root and band_lonely.

HEADER = (
    "import LonelyRunner.LRC.Spec.BandCoverCoreN\n\n"
    "/-!\n"
    "# The band cover, part {part}: the subtree under root cut {part}\n\n"
    "Generated by `LonelyRunner/experiments/nN/redo/gen_band_lean_v2.py` from the certified wall-cut tree\n"
    "`band_cover_tree_v3.json.gz` (E124, independently checked).  Every node's region is carried as hypotheses; each cell\n"
    "is `cone_band` (pairwise laps) with every wall proved by `linarith only` from its certificate's rows; empty regions\n"
    "are refuted by `linarith only`.  Running record: `RUNNING_LOG_order8_v1.md` E169.  No `sorry`, no `native_decide`.\n"
    "-/\n\n"
    "set_option maxHeartbeats 4000000\n"
    "set_option linter.style.longLine false\n"
    "set_option linter.unusedVariables false\n\n"
    "namespace LRC.BandCover\n\n")

FINAL_DOC = (
    "\n/-!\n"
    "# The band theorem, in Lean\n\n"
    "Running record: `RUNNING_LOG_order8_v1.md` E169.\n\n"
    "**`band_lonely`**: seven readings `1 = s₀ ≤ s₁ ≤ … ≤ s₆` (the nearest runner at `1`) with `7 ≤ s₆ ≤ 9` are lonely:\n"
    "some `t > 0` has every reading at least `1/8` from the subject.  This is the band of spread 7–9, every real shape in\n"
    "it, including the late shapes whose cascade lands in the nearest runner's second clear stretch.  The proof is the\n"
    "certified wall-cut cover of E124 (105 lap-assignment cells, 7,019 nodes): each cell one rule (`cone_band`, pairwise\n"
    "laps), the exhaustion by linear certificates, all re-checked here by Lean.  No `sorry`, no `native_decide`.\n"
    "-/\n\n"
    "set_option maxHeartbeats 4000000\n"
    "set_option linter.style.longLine false\n"
    "set_option linter.unusedVariables false\n\n"
    "namespace LRC.BandCover\n\n")

BAND = (
    "/-- **The band theorem.** -/\n"
    "theorem band_lonely (s1 s2 s3 s4 s5 s6 : ℝ) (h1 : 1 ≤ s1) (h12 : s1 ≤ s2) (h23 : s2 ≤ s3) (h34 : s3 ≤ s4)\n"
    "    (h45 : s4 ≤ s5) (h56 : s5 ≤ s6) (h6lo : 7 ≤ s6) (h6hi : s6 ≤ 9) :\n"
    "    ∃ t : ℝ, 0 < t ∧ ∀ i, (8 : ℝ)⁻¹ ≤ circDist (bandS (s1 - 1) (s2 - 1) (s3 - 1) (s4 - 1) (s5 - 1) (s6 - 1) i * t) :=\n"
    "  bc_root (s1 - 1) (s2 - 1) (s3 - 1) (s4 - 1) (s5 - 1) (s6 - 1) (by linarith) (by linarith) (by linarith)\n"
    "    (by linarith) (by linarith) (by linarith) (by linarith) (by linarith) (by linarith) (by linarith) (by linarith)\n"
    "    (by linarith) (by linarith)\n\n"
    "end LRC.BandCover\n")

rootrec = tree['']
tops = [str(m) for m in range(len(rootrec['cut']))]
by_top = {t: [] for t in tops}
for key in order:
    if key == '':
        continue
    by_top[key.split(',')[0]].append(key)
os.makedirs(OUT, exist_ok=True)
tops = [t for t in tops if by_top[t]]
for t in tops:
    txt = HEADER.format(part=t) + "\n".join(lemma(k) for k in by_top[t]) + "\nend LRC.BandCover\n"
    open(os.path.join(OUT, "BandCoverTree%sN.lean" % t), "w").write(txt)
imports = "\n".join("import LonelyRunner.LRC.Spec.BandCoverTree%sN" % t for t in tops)
final = imports + "\n" + FINAL_DOC + lemma('') + "\n" + BAND
open(os.path.join(OUT, "BandCoverN.lean"), "w").write(final)
sizes = {t: os.path.getsize(os.path.join(OUT, "BandCoverTree%sN.lean" % t)) // 1024 for t in tops}
print("modules:", len(tops), "sizes kB:", sizes, "lemmas:", len(order))
